        salida << " { grupo " << nombre;
        for (const Registro& registro : grupo.registros) {
            salida << ' ' << registro.id << registro.recuento;
        }
        salida << " }";
    }
    salida << " }";
    if (!salida) { return false; }
    destino = salida.str();
    return true;
}

